import{_ as r,l as c,o as e,c as l,v as t,p as n,x as i,d as o,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"包含与互斥层次","description":"","frontmatter":{"title":"包含与互斥层次","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/inclusive-exclusive-cache.md","filePath":"cs/inclusive-exclusive-cache.md","lastUpdated":1789023840000}'),L={name:"cs/inclusive-exclusive-cache.md"};function d(E,a,A,u,_,B){const s=c("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="包含与互斥层次" tabindex="-1">包含与互斥层次 <a class="header-anchor" href="#包含与互斥层次" aria-label="Permalink to &quot;包含与互斥层次&quot;">​</a></h1><div class="epigraph"><p>L2 可以规定必须拥有 L1 的每一行，也可以规定与 L1 不重叠；作废与容量在两种约定下走相反的路。</p><footer>—— 据 Hennessy and Patterson, Computer Architecture: A Quantitative Approach 整理</footer></div><p><a href="/cs/cache-prefetch">上一课</a>允许把块提前填进某一层。多层 cache 至此仍像独立的 SRAM。<a href="/cs/write-back-allocate">写回与写分配</a>只处理相邻两层的脏。本课不重讲预取步长。缺口是层次之间的包含关系：包含（inclusive）让下层成为上层的超集，便于探听过滤；互斥（exclusive）让块只在一层，容量相加。本课只钉这两种约定，不引入目录。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>私有 L1 加共享 L2 时，探听「某核有没有这行」若必须问遍所有 L1，延迟大。若 L2 包含所有 L1 行，L2 缺失即可断言 L1 也无，探听可以先看 L2。代价：L1 的行占 L2 容量，有效缓存变小；L2 替换一行必须把 L1 里的副本也作废。</p><p>互斥：L1 命中的行从 L2 拿掉，总容量接近相加。探听不能只看 L2。缺口不是新的相联度，而是<strong>替换与作废时要不要维持「在上则必在下」</strong>。</p><p><span class="marginnote">Intel 许多客户端 LLC 偏包含，便于探听；部分 AMD L2/L3 偏互斥，把容量加满。教学只取这两种理想端点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>包含：填 L1 时也保证 L2 有该块（或稍后写回保持）。L2 驱逐 → 向 L1 发回溯作废/写回。预取填 L3 时，包含层次可能要求中间层也知道。</p><p>互斥：L1 缺失从 L2 取走该行（swap 或使 L2 无效）。L1 驱逐再放回 L2。两层不要长期存同一副本。</p>',10)),(e(),n(h,null,{default:i(()=>[p(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20INC%5B%22%E5%8C%85%E5%90%AB%EF%BC%9AL2%20%E2%8A%87%20L1%22%5D%20--%3E%20BK%5B%22L2%20%E6%9B%BF%E6%8D%A2%E9%A1%BB%E5%9B%9E%E6%BA%AF%20L1%22%5D%0A%20%20EXC%5B%22%E4%BA%92%E6%96%A5%EF%BC%9A%E5%9D%97%E5%8F%AA%E5%9C%A8%E4%B8%80%E5%B1%82%22%5D%20--%3E%20ADD%5B%22%E5%AE%B9%E9%87%8F%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20INC%20--%3E%20FLT%5B%22L2%20%E5%8F%AF%E8%BF%87%E6%BB%A4%E6%8E%A2%E5%90%AC%22%5D%0A%20%20EXC%20--%3E%20SNP%5B%22%E6%8E%A2%E5%90%AC%E9%A1%BB%E7%9C%8B%20L1%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>非包含（non-inclusive）介于中间：不保证超集，也不主动互斥。本课点名存在，不展开状态机。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>包含把一致性的「有没有副本」下推到更大的那一层，和后课窥探/目录衔接。互斥与预取：预取进 L2 不会自动出现在 L1，L1 冷缺失仍在；包含则可能让预取同时占两层容量。</p><p><a href="/cs/cache-miss-types">缺失分类</a>在多层要按层说：L1 冲突、L2 容量。包含使 L2 的有效 \\(C\\) 小于标称容量。这是阿姆达尔项里「加大 L2」收益变小的原因之一。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MESI，不处理多核。虚拟内存下一课改的是地址空间，不是这套包含约定；页表走访会经过这些 cache，包含关系照旧。也不把指令/数据 L1 的互斥当成第三种主策略。</p><p>后课默认：谈到多层，先问包含还是互斥。程序员仍看见虚拟地址；翻译是分页课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>包含：下层超集，替换须回溯，探听可过滤。</li><li>互斥：块只在一层，容量相加，探听更贵。</li><li>虚拟页与页表是下一课；本课只收 cache 层次约定。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em> 多层 cache 包含性。</li></ul>',9))])}const C=r(L,[["render",d]]);export{f as __pageData,C as default};
